7	\begin{enumerate}
8	    \item 生成候选答案；
9	    \item 用规则或程序验证器给出可验证奖励；
10	    \item 用 RL 更新策略，提高高奖励样本概率。
11	\end{enumerate}
12	\end{importantbox}
